          BRK: 15,
          RET: 111,
          RETI: 127,
          CLRP: 32,
          SETP: 64,
          CLRC: 96,
          SETC: 128,
          EI: 160,
          DI: 192,
          CLRV: 224,
          NOTC: 237,
          SLEEP: 239,
          STOP: 255,
          XCN: 159
