          "A,$": { byte: 228, word: 229 },
          "A,$+X": { byte: 244, word: 245 },
          "X,$": { byte: 248, word: 233 },
          "Y,$": { byte: 235, word: 236 },
          "$,A": { byte: 196, word: 197 },
          "$+X,A": { byte: 212, word: 213 },
          "$,X": { byte: 216, word: 201 },
